// TaskFilter provides filtering for Task queries
type TaskFilter struct {
	Id              *UUIDFilter
	Title           *StringFilter
	Owner           *UUIDFilter
	Reviewer        *UUIDFilter
	Plan            *StringFilter
	Proof           *StringFilter
	Urgent          *BoolFilter
	Attempts        *FloatFilter
	CreatedBy       *UUIDFilter
	Status          *StringFilter
	StatusEnteredAt *DateTimeFilter
	Version         *Int64Filter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []TaskFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []TaskFilter
}

// TaskUpdate provides fields that can be updated
type TaskUpdate struct {
	Title           *string
	Owner           *types.IdentityUUID
	Reviewer        *types.IdentityUUID
	ReviewerSetNull bool
	Plan            *string
	PlanSetNull     bool
	Proof           *string
	ProofSetNull    bool
	Urgent          *bool
	Attempts        *float64
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewTaskSnapshotUpdate maps every mutable field from a complete
// Task value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewTaskSnapshotUpdate(input *types.Task) *TaskUpdate {
	update := &TaskUpdate{}
	if input == nil {
		return update
	}
	update.Title = &input.Title
	update.Owner = &input.Owner
	if input.Reviewer == nil {
		update.ReviewerSetNull = true
	} else {
		update.Reviewer = input.Reviewer
	}
	var zeroPlan string
	if input.Plan == zeroPlan {
		update.PlanSetNull = true
	} else {
		update.Plan = &input.Plan
	}
	var zeroProof string
	if input.Proof == zeroProof {
		update.ProofSetNull = true
	} else {
		update.Proof = &input.Proof
	}
	update.Urgent = &input.Urgent
	update.Attempts = &input.Attempts
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *TaskUpdate) ApplyTo(row *types.Task) {
	if u == nil || row == nil {
		return
	}
	if u.Title != nil {
		row.Title = *u.Title
	}
	if u.Owner != nil {
		row.Owner = *u.Owner
	}
	if u.ReviewerSetNull {
		row.Reviewer = nil
	} else if u.Reviewer != nil {
		row.Reviewer = u.Reviewer
	}
	if u.PlanSetNull {
		var zeroPlan string
		row.Plan = zeroPlan
	} else if u.Plan != nil {
		row.Plan = *u.Plan
	}
	if u.ProofSetNull {
		var zeroProof string
		row.Proof = zeroProof
	} else if u.Proof != nil {
		row.Proof = *u.Proof
	}
	if u.Urgent != nil {
		row.Urgent = *u.Urgent
	}
	if u.Attempts != nil {
		row.Attempts = *u.Attempts
	}
}

// TaskFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func TaskFilterConditions(filter *TaskFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a TaskFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *TaskFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

